package com.digitalbase.ticketing.repository;import com.digitalbase.ticketing.enums.TicketStatus;import com.digitalbase.ticketing.model.Ticket;import org.springframework.data.jpa.domain.Specification;import java.time.Instant;import java.util.List; // 👈 List ကို Import လုပ်ရန် လိုအပ်ပါသည်public class TicketSpecification {    public static Specification<Ticket> hasStatus(TicketStatus status) {        return (root, query, cb) -> status == null ? null : cb.equal(root.get("status"), status);    }    // သင့်စနစ်တွင် Priority ကို Enum ဖြင့် သတ်မှတ်ထားသည်ဟု ယူဆပါသည် (ဥပမာ Priority.HIGH)    public static Specification<Ticket> hasPriority(String priority) {        return (root, query, cb) -> priority == null || priority.isEmpty() ? null : cb.equal(root.get("priority").as(String.class), priority);    }    public static Specification<Ticket> belongsToCustomer(Long customerId) {        return (root, query, cb) -> customerId == null ? null : cb.equal(root.get("customer").get("id"), customerId);    }    public static Specification<Ticket> assignedToDeveloper(Long developerId) {        return (root, query, cb) -> developerId == null ? null : cb.equal(root.get("developer").get("id"), developerId);    }    public static Specification<Ticket> createdAfter(Instant startDate) {        return (root, query, cb) -> startDate == null ? null : cb.greaterThanOrEqualTo(root.get("createdAt"), startDate);    }    // End Date ထက် ငယ်သော သို့မဟုတ် ညီသော (<=)    public static Specification<Ticket> createdBefore(Instant endDate) {        return (root, query, cb) -> endDate == null ? null : cb.lessThanOrEqualTo(root.get("createdAt"), endDate);    }    // 🎯 [အသစ်ထပ်ဖြည့်ခြင်း] Product ID (ClientProduct ID များ) ဖြင့် Filter လုပ်ရန်    public static Specification<Ticket> belongsToClientProducts(List<Long> clientProductIds) {        return (root, query, cb) -> {            if (clientProductIds == null || clientProductIds.isEmpty()) {                // List အလွတ်ဖြစ်နေပါက Ticket မပြရန် false return ပြန်သည် (သို့မဟုတ်) cb.disjunction() သုံးနိုင်သည်                return cb.disjunction();            }            return root.get("clientProduct").get("id").in(clientProductIds);        };    }    // 🎯 Client Product ID တစ်ခုတည်းဖြင့် Filter လုပ်ရန်    public static Specification<Ticket> belongsToClientProduct(Long clientProductId) {        return (root, query, cb) -> clientProductId == null ? null : cb.equal(root.get("clientProduct").get("id"), clientProductId);    }}